# markerDB.prep.R
# This script demonstrates how markerDB and the tissueTypes were prepared

# Load necessary libraries
library(readxl)
library(dplyr)
library(Matrix)

#______________________________

## Function to convert table to sparse marker x (Tissue_CellType) matrix
make_sparse_marker_matrix <- function(df) {
  
  # Ensure required columns exist
  required_cols <- c("Tissue", "Condition", "CellType", "Marker")
  if (!all(required_cols %in% names(df))) {
    stop("Input data frame must contain columns: Tissue, Condition, CellType, Marker")
  }
  
  # Create unique combination column
  df <- df %>%
    mutate(Combo = paste(Tissue, Condition, CellType, sep = "_"))
  
  # Define levels for markers and combos
  marker_levels <- unique(df$Marker)
  combo_levels <- unique(df$Combo)
  
  # Map to indices
  i <- match(df$Marker, marker_levels)
  j <- match(df$Combo, combo_levels)
  
  # Construct sparse binary matrix
  sparse_mat <- sparseMatrix(
    i = i,
    j = j,
    x = 1,
    dims = c(length(marker_levels), length(combo_levels)),
    dimnames = list(marker_levels, combo_levels)
  )
  
  return(sparse_mat)
}

