# Create a cleaned version of the data with only the best entry per Marker
markerDictionary$human <- markerDictionary$human %>%
  # Replace empty strings with NA for accurate counting
  mutate(across(-Marker, ~ na_if(trimws(.), ""))) %>%
  # Count how many non-NA columns each row has (excluding Marker)
  mutate(non_missing_count = rowSums(!is.na(across(-Marker)))) %>%
  # Arrange to keep the best row per Marker
  arrange(Marker, desc(non_missing_count)) %>%
  # Keep only the first (best) entry per Marker
  distinct(Marker, .keep_all = TRUE) %>%
  # Drop helper column
  dplyr::select(-non_missing_count)

markerDictionary$human <- markerDictionary$human[-which(nchar(markerDictionary$human$Marker) <= 1),]
markerDictionary$human <- markerDictionary$human[-which(!is.na(as.numeric(markerDictionary$human$Marker))),]
