#_______________

download.file("https://storage.googleapis.com/public-download-files/hgnc/tsv/tsv/non_alt_loci_set.txt", destfile = "Cell Marker Databases/HGNC_genenamesDB.txt")
HGNC_genenamesDB <- read.delim("Cell Marker Databases/HGNC_genenamesDB.txt", sep = "\t")
HGNC_genenamesDB[is.na(HGNC_genenamesDB)] <- ""

HGNC_genenamesDB$all_alias <- sapply(seq(nrow(HGNC_genenamesDB)), function(i) {
  curr_collapse <- ifelse((HGNC_genenamesDB$alias_symbol[i] != "" & HGNC_genenamesDB$prev_symbol[i] != ""), "|", "")
  paste0(c(HGNC_genenamesDB$alias_symbol[i], HGNC_genenamesDB$prev_symbol[i]), collapse = curr_collapse)
})

HGNC_genenamesDB$all_alias_plusName <- sapply(seq(nrow(HGNC_genenamesDB)), function(i) {
  curr_collapse <- ifelse((HGNC_genenamesDB$symbol[i] != "" & HGNC_genenamesDB$all_alias[i] != ""), "|", "")
  paste0(c(HGNC_genenamesDB$symbol[i], HGNC_genenamesDB$all_alias[i]), collapse = curr_collapse)
})

markerDictionary$human$Symbol[which(markerDictionary$human$Ensembl %in%  HGNC_genenamesDB$ensembl_gene_id)] <- 
  HGNC_genenamesDB$symbol[match(markerDictionary$human$Ensembl[which(markerDictionary$human$Ensembl %in%  HGNC_genenamesDB$ensembl_gene_id)], HGNC_genenamesDB$ensembl_gene_id)]

markerDictionary$human$Entrez[which(markerDictionary$human$Ensembl %in%  HGNC_genenamesDB$ensembl_gene_id)] <- 
  HGNC_genenamesDB$entrez_id[match(markerDictionary$human$Ensembl[which(markerDictionary$human$Ensembl %in%  HGNC_genenamesDB$ensembl_gene_id)], HGNC_genenamesDB$ensembl_gene_id)]

markerDictionary$human$Symbol[which(markerDictionary$human$Entrez %in%  HGNC_genenamesDB$entrez_id)] <- 
  HGNC_genenamesDB$symbol[match(markerDictionary$human$Entrez[which(markerDictionary$human$Entrez %in%  HGNC_genenamesDB$entrez_id)], HGNC_genenamesDB$entrez_id)]

markerDictionary$human$Ensembl[which(markerDictionary$human$Entrez %in%  HGNC_genenamesDB$entrez_id)] <- 
  HGNC_genenamesDB$ensembl_gene_id[match(markerDictionary$human$Entrez[which(markerDictionary$human$Entrez %in%  HGNC_genenamesDB$entrez_id)], HGNC_genenamesDB$entrez_id)]

markerDictionary$human$Entrez[is.na(markerDictionary$human$Entrez)] <- sapply(which(is.na(markerDictionary$human$Entrez)), function(i) {
  tmp_check <- sapply(seq(nrow(HGNC_genenamesDB)), function(j) {
    tmp_names <- str_split(HGNC_genenamesDB$all_alias_plusName[j], pattern = "\\|") %>% unlist() %>% unname()
    tmp_match <- which(tmp_names %in% markerDictionary$human$Marker[i])
    if(length(tmp_match) > 0) {
      return(HGNC_genenamesDB$entrez_id[j])
    } else {
      NULL
    }
  }) %>% unlist()
  if(length(tmp_check) > 0) {
    markerDictionary$human$Entrez[i] <- tmp_check
  }
})

markerDictionary_human_Entrez_ensembl <- sapply(markerDictionary$human$Entrez, 
                                                function(i) (unlist(i) %>% unname)[1] %>% unlist())
markerDictionary_human_Entrez_ensembl[sapply(markerDictionary_human_Entrez_ensembl, function(i) is.null(i))] <- NA
markerDictionary_human_Entrez_ensembl <- unlist(markerDictionary_human_Entrez_ensembl)
markerDictionary$human$Entrez <- markerDictionary_human_Entrez_ensembl

markerDictionary$human$Entrez[which(markerDictionary$human$Marker %in%  HGNC_genenamesDB$symbol)] <- 
  HGNC_genenamesDB$entrez_id[match(markerDictionary$human$Marker[which(markerDictionary$human$Marker %in%  HGNC_genenamesDB$symbol)], HGNC_genenamesDB$symbol)]

markerDictionary$human$Ensembl[which(markerDictionary$human$Entrez %in%  HGNC_genenamesDB$entrez_id)] <- 
  HGNC_genenamesDB$ensembl_gene_id[match(markerDictionary$human$Entrez[which(markerDictionary$human$Entrez %in%  HGNC_genenamesDB$entrez_id)], HGNC_genenamesDB$entrez_id)]

markerDictionary$human$Ensembl[which(markerDictionary$human$Marker %in%  HGNC_genenamesDB$symbol)] <- 
  HGNC_genenamesDB$ensembl_gene_id[match(markerDictionary$human$Marker[which(markerDictionary$human$Marker %in%  HGNC_genenamesDB$symbol)], HGNC_genenamesDB$symbol)]

markerDictionary$human$Symbol[which(markerDictionary$human$Marker %in%  HGNC_genenamesDB$symbol)] <- 
  HGNC_genenamesDB$symbol[match(markerDictionary$human$Marker[which(markerDictionary$human$Marker %in%  HGNC_genenamesDB$symbol)], HGNC_genenamesDB$symbol)]

markerDictionary$human$Symbol[which(markerDictionary$human$Entrez %in%  HGNC_genenamesDB$entrez_id)] <- 
  HGNC_genenamesDB$symbol[match(markerDictionary$human$Entrez[which(markerDictionary$human$Entrez %in%  HGNC_genenamesDB$entrez_id)], HGNC_genenamesDB$entrez_id)]

markerDictionary$human$UniProt[which(markerDictionary$human$Entrez %in%  HGNC_genenamesDB$entrez_id)] <- 
  HGNC_genenamesDB$uniprot_ids[match(markerDictionary$human$Entrez[which(markerDictionary$human$Entrez %in%  HGNC_genenamesDB$entrez_id)], HGNC_genenamesDB$entrez_id)]

#_______

library(data.table)

# Convert to data.table
dt_human <- as.data.table(markerDictionary$human)
dt_hgnc <- as.data.table(HGNC_genenamesDB)

# Explode alias strings into long format
dt_hgnc_expanded <- dt_hgnc[, .(alias = unlist(strsplit(all_alias_plusName, "\\|", fixed = FALSE))), by = symbol]

# Lowercase for case-insensitive match (optional, improves performance over regex `ignore.case`)
dt_hgnc_expanded[, alias_lower := tolower(alias)]
dt_human[, Marker_lower := tolower(Marker)]

# Only process rows where Symbol is NA
na_rows <- which(is.na(dt_human$Symbol))

# Join: fast lookup for matching aliases
matched <- merge(
  dt_human[na_rows, .(row_id = .I, Marker_lower)],
  dt_hgnc_expanded[, .(alias_lower, symbol)],
  by.x = "Marker_lower", by.y = "alias_lower", all.x = TRUE
)

# Update the Symbol column in the original data
dt_human[na_rows[matched$row_id], Symbol := matched$symbol]

# Replace back into markerDictionary
markerDictionary$human <- as.data.frame(dt_human)

markerDictionary$human$Marker_lower <- NULL

markerDictionary$human$Entrez[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)] <- 
  HGNC_genenamesDB$entrez_id[match(markerDictionary$human$Symbol[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)], HGNC_genenamesDB$symbol)]

markerDictionary$human$Ensembl[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)] <- 
  HGNC_genenamesDB$ensembl_gene_id[match(markerDictionary$human$Symbol[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)], HGNC_genenamesDB$symbol)]

markerDictionary$human$UniProt[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)] <- 
  HGNC_genenamesDB$uniprot_ids[match(markerDictionary$human$Symbol[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)], HGNC_genenamesDB$symbol)]

# Renaming the Nikname to Alias
markerDictionary$human <- markerDictionary$human %>% dplyr::rename(Alias = Niknames)
markerDictionary$human <- markerDictionary$human %>% dplyr::select(Marker, Symbol, Alias, Entrez, Ensembl, UniProt)

markerDictionary$human$Alias[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)] <- 
  HGNC_genenamesDB$all_alias[match(markerDictionary$human$Symbol[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)], HGNC_genenamesDB$symbol)]

# NOTE some marker names such as ΑΡΟΕ are in latin. We need to correct them

## Defining a custom mapping vector
custom_map <- c(
  # Uppercase
  "Α" = "A", "Β" = "B", "Ε" = "E", "Ζ" = "Z", "Η" = "H",
  "Ι" = "I", "Κ" = "K", "Μ" = "M", "Ν" = "N", "Ο" = "O",
  "Ρ" = "P", "Τ" = "T", "Υ" = "Y", "Χ" = "X",
  # Lowercase
  "α" = "a", "β" = "b", "ε" = "e", "η" = "n", "ι" = "i",
  "κ" = "k", "ν" = "v", "ο" = "o", "ρ" = "p", "τ" = "t",
  "υ" = "y", "χ" = "x", "γ" = "y", "ω" = "w", "ζ" = "z"
)

markerDictionary$human <- markerDictionary$human %>%
  mutate(Marker_Latin = stringr::str_replace_all(Marker, custom_map))

#_____________________

library(data.table)

# Convert to data.table
dt_human <- as.data.table(markerDictionary$human)
dt_hgnc <- as.data.table(HGNC_genenamesDB)

# Expand aliases
dt_hgnc_expanded <- dt_hgnc[, .(alias = unlist(strsplit(all_alias_plusName, "\\|", fixed = FALSE))), by = symbol]

# Lowercase and trim for clean matching
dt_hgnc_expanded[, alias_lower := trimws(tolower(alias))]
dt_human[, Marker_lower := trimws(tolower(Marker_Latin))]

# Merge all rows based on lowercased markers and aliases
matched <- merge(
  dt_human[, .(row_id = .I, Marker_lower)],
  dt_hgnc_expanded[, .(alias_lower, symbol)],
  by.x = "Marker_lower", by.y = "alias_lower",
  all.x = TRUE
)

# Use matched$symbol to update the Symbol column
dt_human[matched$row_id, Symbol := matched$symbol]

# Replace back into markerDictionary
markerDictionary$human <- as.data.frame(dt_human)
markerDictionary$human$Marker_lower <- NULL

markerDictionary$human$Entrez[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)] <- 
  HGNC_genenamesDB$entrez_id[match(markerDictionary$human$Symbol[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)], HGNC_genenamesDB$symbol)]

markerDictionary$human$Ensembl[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)] <- 
  HGNC_genenamesDB$ensembl_gene_id[match(markerDictionary$human$Symbol[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)], HGNC_genenamesDB$symbol)]

markerDictionary$human$UniProt[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)] <- 
  HGNC_genenamesDB$uniprot_ids[match(markerDictionary$human$Symbol[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)], HGNC_genenamesDB$symbol)]

markerDictionary$human$Alias[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)] <- 
  HGNC_genenamesDB$all_alias[match(markerDictionary$human$Symbol[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)], HGNC_genenamesDB$symbol)]

# Re-do

markerDictionary$human$Marker_Latin2 <- markerDictionary$human$Marker_Latin
markerDictionary$human$Marker_Latin2 <- gsub(pattern = "a-", replacement = "alpha-", markerDictionary$human$Marker_Latin2)
markerDictionary$human$Marker_Latin2 <- gsub(pattern = "b-", replacement = "beta-", markerDictionary$human$Marker_Latin2)
markerDictionary$human$Marker_Latin2 <- gsub(pattern = "b‐", replacement = "beta-", markerDictionary$human$Marker_Latin2)
markerDictionary$human$Marker_Latin2 <- gsub(pattern = "y-", replacement = "gamma-", markerDictionary$human$Marker_Latin2)

# Convert to data.table
dt_human <- as.data.table(markerDictionary$human)
dt_hgnc <- as.data.table(HGNC_genenamesDB)

# Expand aliases
dt_hgnc_expanded <- dt_hgnc[, .(alias = unlist(strsplit(all_alias_plusName, "\\|", fixed = FALSE))), by = symbol]

# Lowercase and trim for clean matching
dt_hgnc_expanded[, alias_lower := trimws(tolower(alias))]
dt_human[, Marker_lower := trimws(tolower(Marker_Latin2))]

# Merge all rows based on lowercased markers and aliases
matched <- merge(
  dt_human[, .(row_id = .I, Marker_lower)],
  dt_hgnc_expanded[, .(alias_lower, symbol)],
  by.x = "Marker_lower", by.y = "alias_lower",
  all.x = TRUE
)

# Use matched$symbol to update the Symbol column
dt_human[matched$row_id, Symbol := matched$symbol]

# Replace back into markerDictionary
markerDictionary$human <- as.data.frame(dt_human)

markerDictionary$human$Marker_lower <- NULL

markerDictionary$human$Entrez[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)] <- 
  HGNC_genenamesDB$entrez_id[match(markerDictionary$human$Symbol[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)], HGNC_genenamesDB$symbol)]

markerDictionary$human$Ensembl[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)] <- 
  HGNC_genenamesDB$ensembl_gene_id[match(markerDictionary$human$Symbol[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)], HGNC_genenamesDB$symbol)]

markerDictionary$human$UniProt[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)] <- 
  HGNC_genenamesDB$uniprot_ids[match(markerDictionary$human$Symbol[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)], HGNC_genenamesDB$symbol)]

markerDictionary$human$Alias[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)] <- 
  HGNC_genenamesDB$all_alias[match(markerDictionary$human$Symbol[which(markerDictionary$human$Symbol %in%  HGNC_genenamesDB$symbol)], HGNC_genenamesDB$symbol)]

#_____________________________________________

# Final Data Filtration
markerDictionary$human <- markerDictionary$human %>% dplyr::filter(!is.na(Symbol))

