# Clean tissue names
clean_tissue <- function(tissue_vec) {
  cleaned <- tissue_vec %>%
    tolower() %>%                            # Make everything lowercase
    str_trim() %>%                           # Trim whitespace
    str_replace_all("_", " ") %>%
    str_replace_all("-", " ") %>%
    str_replace_all(" +", " ")              # Collapse multiple spaces
  return(cleaned)
}

