# General cleaner
clean_condition <- function(condition_vec) {
  cleaned <- condition_vec %>%
    tolower() %>%
    str_trim() %>%
    str_replace_all(" +", " ") %>%
    str_replace_all("-", " ") %>%
    str_replace_all("\\bnon hodgkin'?s? lymphoma\\b", "non-hodgkin lymphoma") %>%
    na_if("")
  return(cleaned)
}

