clean_celltype1 <- function(cell_vec) {
  cell_vec %>%
    iconv(from = "", to = "UTF-8", sub = "") %>%                        # remove invalid chars
    stringr::str_replace_all("[\uFF00-\uFFFF]", "_") %>%               # replace full-width/special characters
    tolower() %>%
    stringr::str_trim() %>%
    stringr::str_replace_all("α", "alpha") %>%
    stringr::str_replace_all("\\(.*?\\)", "") %>%
    stringr::str_replace_all("[^a-z0-9+ ]", " ") %>%                   # remove non-alphanumeric
    stringr::str_replace_all("\\s+", " ") %>%
    stringr::str_trim()
}

