## Update Tissue names

clean_celltype_tissue <- function(df) {
  df %>%
    dplyr::mutate(
      # Extract tissue name after "of" or "of the"
      extracted_tissue = case_when(
        # Handle special case: "Basal Cell of Epithelium of Trachea"
        stringr::str_detect(CellType, "^Basal Cell of Epithelium of ") ~ str_extract(CellType, "(?<=Basal Cell of ).*$"),
        # Handle "of the" pattern
        stringr::str_detect(CellType, " of the ") ~ str_extract(CellType, "(?<= of the ).*$"),
        # Handle "of" pattern
        stringr::str_detect(CellType, " of ") ~ str_extract(CellType, "(?<= of ).*$"),
        # If no "of" or "of the", keep Tissue as is
        TRUE ~ NA_character_
      ),
      # Update Tissue column: use extracted tissue if not NA, else keep original Tissue
      Tissue = case_when(
        !is.na(extracted_tissue) ~ str_replace(extracted_tissue, "^the ", ""),
        TRUE ~ Tissue
      ),
      # Update CellType: remove tissue name after "of" or "of the"
      CellType = case_when(
        # Special case: "Basal Cell of Epithelium of Trachea" -> "Basal Cell"
        stringr::str_detect(CellType, "^Basal Cell of Epithelium of ") ~ "Basal Cell",
        # Remove everything after "of the"
        stringr::str_detect(CellType, " of the ") ~ str_extract(CellType, "^.*?(?= of the )"),
        # Remove everything after "of"
        stringr::str_detect(CellType, " of ") ~ str_extract(CellType, "^.*?(?= of )"),
        # Keep CellType as is if no pattern matched
        TRUE ~ CellType
      )
    ) %>%
    # Remove temporary extracted_tissue column
    dplyr::select(-extracted_tissue)
}

human_pos_marker_db_chunk1 <- human_pos_marker_db_chunk1 %>% clean_celltype_tissue()

human_pos_marker_db_chunk1$CellType[
