clean_celltype3 <- function(x) {
  x %>%
    # Lowercase
    stringr::str_to_lower() %>%
    
    # Replace Greek letters with their names
    stringr::str_replace_all("α", "alpha") %>%
    stringr::str_replace_all("β", "beta") %>%
    stringr::str_replace_all("γ", "gamma") %>%
    stringr::str_replace_all("δ", "delta") %>%
    
    # Replace non-informative punctuation but keep biologically relevant characters
    stringr::str_replace_all("[^a-z0-9\\(\\)\\[\\]\\+\\-\\/\\s]", "") %>%
    
    # Collapse multiple spaces
    stringr::str_replace_all("\\s+", " ") %>%
    
    # Trim
    stringr::str_trim()
}

