clean_celltype4 <- function(celltype) {
  celltype <- trimws(tolower(celltype))
  celltype <- gsub(" cells\\b", " cell", celltype)
  celltype <- gsub(" t cells\\b", " t cell", celltype)
  celltype <- gsub("alpha", "a", celltype)
  celltype <- gsub("beta", "b", celltype)
  celltype <- gsub("\\s+", " ", celltype)
  celltype
}

