human_pos_marker_db_chunk4 <- human_pos_marker_db_chunk4 %>%
  mutate(
    Cleaned_CellType = clean_celltype4(Original_CellType),
    Standard_CellType = dplyr::recode(Cleaned_CellType, !!!celltype_map4),
    Standard_CellType = ifelse(is.na(Standard_CellType), stringr::str_to_title(Cleaned_CellType), Standard_CellType)
  ) %>% 
  mutate(CellType = Standard_CellType) %>% 
  dplyr::select(-c(Cleaned_CellType, Standard_CellType))

human_pos_marker_db_chunk4 %>% dplyr::select(CellType) %>% distinct() %>% view()
human_pos_marker_db_chunk4 %>% dplyr::select(CellType) %>% distinct() %>% print(n = 500)

