human_pos_marker_db_chunk4$CellType <- gsub("^Exhausted Double-Positive T Cell$", "Exhausted DP T Cell", human_pos_marker_db_chunk4$CellType) # State

human_pos_marker_db_chunk4$CellType <- gsub("^F-Pericyte$", "Pericyte", human_pos_marker_db_chunk4$CellType) # Assume F is a specific classification

human_pos_marker_db_chunk4$CellType <- gsub("^Fibrotically Activated Macrophage$", "Fibrosis-Activated Macrophage", human_pos_marker_db_chunk4$CellType)

# --- Highly Specific/Marker-Defined Subtypes (Keep as is, but standardize naming if needed) ---

# These are highly specific due to marker expression, often representing research-specific classifications.
# They are kept as is, but ensure consistent formatting.
human_pos_marker_db_chunk4$CellType <- gsub("^EMT-like Cancer Stem Cell$", "EMT Cancer Stem Cell", human_pos_marker_db_chunk4$CellType)
human_pos_marker_db_chunk4$CellType <- gsub("^Epithelial-Mesenchymal Transition Cancer Stem Cell$", "EMT Cancer Stem Cell", human_pos_marker_db_chunk4$CellType) # Use common abbreviation

human_pos_marker_db_chunk4$CellType <- gsub("^FGFR1HighNME5- Epithelial Cell$", "FGFR1+NME5- Epithelial Cell", human_pos_marker_db_chunk4$CellType)
human_pos_marker_db_chunk4$CellType <- gsub("^FGFR1LowNME5- Epithelial Cell$", "FGFR1-low NME5-negative Epithelial Cell", human_pos_marker_db_chunk4$CellType)
human_pos_marker_db_chunk4$CellType <- gsub("^ECM1 Cell\\+ Basal Cell$", "ECM1+ Basal Cell", human_pos_marker_db_chunk4$CellType) # Remove "Cell" redundancy

human_pos_marker_db_chunk4$CellType <- gsub("^Fusiform Cerebral Cell$", "Cerebral Fusiform Cell", human_pos_marker_db_chunk4$CellType) # More descriptive
human_pos_marker_db_chunk4$CellType <- gsub("^Extratelencephalic Cell$", "Extratelencephalic Neuron", human_pos_marker_db_chunk4$CellType) # Suggest broad categories

human_pos_marker_db_chunk4$CellType <- gsub("^Dorsal Medial Ganglionic Eminence Precursor Cell$", "Medial Ganglionic Eminence Precursor Cell", human_pos_marker_db_chunk4$CellType) # Specific enough
human_pos_marker_db_chunk4$CellType <- gsub("^Epithelial Cell Type 2$", "Epithelial Cell", human_pos_marker_db_chunk4$CellType) # Needs context
human_pos_marker_db_chunk4$CellType <- gsub("^Epithelial Cell Type 1$", "Epithelial Cell", human_pos_marker_db_chunk4$CellType) # Needs context
human_pos_marker_db_chunk4$CellType <- gsub("^A(\\d) Fibroblast$", "Fibroblast", human_pos_marker_db_chunk4$CellType) # Assuming A1, A2, etc. are not defined subtypes

## Update Tissue names
human_pos_marker_db_chunk4 <- human_pos_marker_db_chunk4 %>% clean_celltype_tissue()

# Function to check if a word starts with a lowercase letter
check_lowercase_start <- function(text) {
  # Split the text into words
  words <- strsplit(text, "\\s+")[[1]]
  
  # Check if any word starts with a lowercase letter
  any(sapply(words, function(word) grepl("^[a-z]", word)))
}

# Function to filter character vector
filter_lowercase_words <- function(char_vector) {
  # Apply the check_lowercase_start function to each element of the vector
  result <- char_vector[sapply(char_vector, check_lowercase_start)]
  
  return(result)
}

