standardize_celltype5 <- function(cell_type_vector, correction_map) {
  
  # 1. GENTLER VECTORIZED CLEANUP: This no longer removes numbers, slashes, or hyphens.
  cleaned_types <- tolower(cell_type_vector)
  cleaned_types <- gsub("\\b(cells?|lymphocytes?|of|the|human)\\b", "", cleaned_types)
  cleaned_types <- gsub("\\s*\\([^\\)]+\\)", "", cleaned_types) # Removes content in (...)
  cleaned_types <- gsub("[,]", " ", cleaned_types) # Only removes commas
  cleaned_types <- gsub("\\s+", " ", cleaned_types)
  cleaned_types <- trimws(cleaned_types)
  
  # Initialize the result vector
  result_vector <- character(length(cell_type_vector))
  
  # --- START OF FIX ---
  # 2. REORDER MAP: Order the map from most specific (longest) to least specific (shortest).
  # This is the key to ensuring the best match is found first in the loop.
  map_order <- order(nchar(names(correction_map)), decreasing = TRUE)
  ordered_map <- correction_map[map_order]
  map_names <- names(ordered_map)
  # --- END OF FIX ---
  
  # 3. VECTORIZED EXACT MATCHING: Find all exact matches at once.
  exact_match_indices <- match(cleaned_types, map_names)
  
  found_indices <- which(!is.na(exact_match_indices))
  if (length(found_indices) > 0) {
    result_vector[found_indices] <- ordered_map[exact_match_indices[found_indices]]
  }
  
  # 4. PARTIAL MATCHING (ON REMAINDER ONLY):
  unmatched_indices <- which(result_vector == "")
  if (length(unmatched_indices) > 0) {
    unmatched_cleaned <- cleaned_types[unmatched_indices]
    
    # This loop now implicitly checks long patterns before short ones.
    for (i in seq_along(ordered_map)) {
      pattern <- map_names[i]
      value <- ordered_map[[i]]
      
      grepl_hits <- grepl(pattern, unmatched_cleaned, fixed = TRUE)
      
      if (any(grepl_hits)) {
        original_hit_indices <- unmatched_indices[grepl_hits]
        result_vector[original_hit_indices] <- value
        
        unmatched_indices <- unmatched_indices[!grepl_hits]
        unmatched_cleaned <- unmatched_cleaned[!grepl_hits]
        
        if (length(unmatched_indices) == 0) break
      }
    }
  }
  
  # 5. FALLBACK (ON FINAL REMAINDER):
  fallback_indices <- which(result_vector == "")
  if (length(fallback_indices) > 0) {
    result_vector[fallback_indices] <- tools::toTitleCase(cleaned_types[fallback_indices])
  }
  
  return(result_vector)
}

