human_pos_marker_db_chunk5$Tissue[human_pos_marker_db_chunk5$CellType == "Idiopathic Pulmonary Fibrosis MyoFibroblast"] <- "Lung"
human_pos_marker_db_chunk5$Condition[human_pos_marker_db_chunk5$CellType == "Idiopathic Pulmonary Fibrosis MyoFibroblast"] <- "Idiopathic Pulmonary Fibrosis"
human_pos_marker_db_chunk5$CellType[human_pos_marker_db_chunk5$CellType == "Idiopathic Pulmonary Fibrosis MyoFibroblast"] <- "Myofibroblast"
human_pos_marker_db_chunk5$CellType <- gsub("MyoFibroblast", "Myofibroblast", human_pos_marker_db_chunk5$CellType, ignore.case = T)
human_pos_marker_db_chunk5$CellType[human_pos_marker_db_chunk5$CellType == "Highly Differentiated Effector CD8+ T Cell"] <- "Effector CD8+ T Cell"
human_pos_marker_db_chunk5$CellType[human_pos_marker_db_chunk5$CellType == "Infiltrating MononuClear Cell"] <- "Infiltrating Mononuclear Leukocyte"
human_pos_marker_db_chunk5$CellType <- gsub("MononuClear", "Mononuclear", human_pos_marker_db_chunk5$CellType, ignore.case = T)
human_pos_marker_db_chunk5$CellType[human_pos_marker_db_chunk5$CellType == "HLA-DRA+ Cell"] <- "Antigen Presenting Cell"
human_pos_marker_db_chunk5$CellType[human_pos_marker_db_chunk5$CellType == "Kidney Collecting Duct Cell Principal Cell"] <- "Collecting Duct Principal Cell"
human_pos_marker_db_chunk5$CellType[human_pos_marker_db_chunk5$CellType == "Kidney Collecting Duct Cell Intercalated Cell"] <- "Collecting Duct Intercalated Cell"
human_pos_marker_db_chunk5$CellType[human_pos_marker_db_chunk5$CellType == "Immune Cell Type A"] <- "Type A Intercalated Cell"
human_pos_marker_db_chunk5$CellType[human_pos_marker_db_chunk5$CellType == "Immune Cell Type B"] <- "Type B Intercalated Cell"

## Hematopoietic and Stem Cells
human_pos_marker_db_chunk5$CellType <- gsub("Hepatic Oval Stem Cell|Hepatic Stem Cell|Hepatic Progenitor Cell", "Hepatic Progenitor Cell", human_pos_marker_db_chunk5$CellType, ignore.case = TRUE)

## Germ Cells
human_pos_marker_db_chunk5$CellType <- gsub("Fetal Germ Cell \\(Mitotic\\)|Germline Stem Cell", "Germ Cell", human_pos_marker_db_chunk5$CellType, ignore.case = TRUE)

## Immune Cells
human_pos_marker_db_chunk5$CellType <- gsub("Natural Killer Cell", "NK Cell", human_pos_marker_db_chunk5$CellType, ignore.case = TRUE)

human_pos_marker_db_chunk5$CellType <- gsub("Immature Transitional B Cell", "Immature B Cell", human_pos_marker_db_chunk5$CellType, ignore.case = TRUE)

## T Cells
human_pos_marker_db_chunk5$CellType <- gsub("CD4\\+ T Helper Cell|Helper T Cell", "CD4+ Helper T Cell", human_pos_marker_db_chunk5$CellType, ignore.case = TRUE)

human_pos_marker_db_chunk5$CellType <- gsub("Layer 2/3 Intratelencephalic Projecting Glutamatergic Neuron", "Layer 2/3 Intratelencephalic Neuron", human_pos_marker_db_chunk5$CellType, ignore.case = TRUE, perl=TRUE)
human_pos_marker_db_chunk5$CellType <- gsub("Layer 5 Intratelencephalic Projecting Glutamatergic Neuron", "Layer 5 Intratelencephalic Neuron", human_pos_marker_db_chunk5$CellType, ignore.case = TRUE, perl=TRUE)
human_pos_marker_db_chunk5$CellType <- gsub("Layer 5/6 Near-Projecting Glutamatergic Neuron", "Layer 5/6 Near-Projecting Neuron", human_pos_marker_db_chunk5$CellType, ignore.case = TRUE, perl=TRUE)
human_pos_marker_db_chunk5$CellType <- gsub("Layer 6 Corticothalamic-Projecting Glutamatergic Cortical Interneuron", "Layer 6 Corticothalamic Neuron", human_pos_marker_db_chunk5$CellType, ignore.case = TRUE, perl=TRUE)
human_pos_marker_db_chunk5$CellType <- gsub("Layer 6 Intratelencephalic Projecting Glutamatergic Neuron", "Layer 6 Intratelencephalic Neuron", human_pos_marker_db_chunk5$CellType, ignore.case = TRUE, perl=TRUE)
human_pos_marker_db_chunk5$CellType <- gsub("Layer 6b Glutamatergic Cortical Interneuron", "Layer 6b Excitatory Neuron", human_pos_marker_db_chunk5$CellType, ignore.case = TRUE, perl=TRUE)
human_pos_marker_db_chunk5$CellType <- gsub("Layer 5 Extratelencephalic Projecting Glutamatergic Cortical Interneuron", "Layer 5 Extratelencephalic Neuron", human_pos_marker_db_chunk5$CellType, ignore.case = TRUE, perl=TRUE)

human_pos_marker_db_chunk5$CellType <- gsub("UnDifferentiated", "Undifferentiated", human_pos_marker_db_chunk5$CellType, ignore.case = TRUE)
human_pos_marker_db_chunk5$CellType[human_pos_marker_db_chunk5$CellType == "Ito"] <- "Ito Cell"

human_pos_marker_db_chunk5$CellType[human_pos_marker_db_chunk5$CellType == "Induced Pluripotent Stem Cell (iPSC)"] <- "Pluripotent Stem Cell"

# Remove wrong digit markers
if(!all(as.integer(human_pos_marker_db_chunk5$Marker) %>% is.na())) {
  human_pos_marker_db_chunk5 <- human_pos_marker_db_chunk5[-(seq(length(human_pos_marker_db_chunk5$Marker))[-(as.integer(human_pos_marker_db_chunk5$Marker) %>% is.na() %>% which())]),]
}

## Update Tissue names
human_pos_marker_db_chunk5 <- human_pos_marker_db_chunk5 %>% clean_celltype_tissue()

