# Assign Cancer-Associated Fibroblast for any Neoplastic Stromal Cell with these markers
human_pos_marker_db_chunk7$CellType[
  human_pos_marker_db_chunk7$CellType == "Neoplastic Stromal Cell" &
    human_pos_marker_db_chunk7$Marker %in% caf_markers
] <- "Cancer-Associated Fibroblast"

# Assign Endothelial Cell for endothelial markers within Neoplastic Stromal Cell
endothelial_markers <- c("PECAM1", "VWF")

human_pos_marker_db_chunk7$CellType[
  human_pos_marker_db_chunk7$CellType == "Neoplastic Stromal Cell" &
    human_pos_marker_db_chunk7$Marker %in% endothelial_markers
] <- "Endothelial Cell"

