standardize_celltype8 <- function(celltypes) {
  # Clean the cell type names
  cleaned <- sapply(celltypes, clean_celltype8)
  
  # Map cleaned names to standardized names
  standardized <- sapply(cleaned, function(x) {
    if (x %in% names(celltype_map8)) {
      return(celltype_map8[[x]])
    } else {
      # If no mapping exists, return cleaned name with title case
      paste0(toupper(substring(x, 1, 1)), substring(x, 2))
    }
  })
  
  return(standardized)
}

