human_pos_marker_db_chunk8$CellType[human_pos_marker_db_chunk8$CellType %in% c("Neuroepithelial Cell", "Neuroepithelial Progenitor", "Neuroepithelial Stem Cell")] <- "Neuroepithelial Cell"
human_pos_marker_db_chunk8$CellType[human_pos_marker_db_chunk8$CellType == "Non-Cycling Cell Germinal Center B Cell"] <- "Germinal Center B Cell"
human_pos_marker_db_chunk8$CellType[human_pos_marker_db_chunk8$CellType == "Non-Keratinizing Barrier Epithelial Cell" & human_pos_marker_db_chunk8$Tissue == "Lung"] <- "Alveolar Type II Cell"
human_pos_marker_db_chunk8$CellType[human_pos_marker_db_chunk8$CellType == "Non-Malignant Epithelial Cell" & human_pos_marker_db_chunk8$Marker %in% c("KRT5","KRT14")] <- "Basal Squamous Epithelial Cell"

human_pos_marker_db_chunk8$CellType[human_pos_marker_db_chunk8$CellType == "Pre-EMT Neural Crest Cell"] <- "Premigratory Neural Crest Cell"
human_pos_marker_db_chunk8$CellType[human_pos_marker_db_chunk8$CellType == "Non-Fenestrated Vasa Recta Cell"] <- "Vasa Recta Descending Limb Endothelial Cell"
# Standardize all pericyte progenitor to "Pericyte"
human_pos_marker_db_chunk8$CellType[human_pos_marker_db_chunk8$CellType == "Pericyte Progenitor"] <- "Pericyte"
# Proliferating variants
human_pos_marker_db_chunk8$CellType[grepl("Pericyte \\(S Phase|G2M Phase\\)", human_pos_marker_db_chunk8$CellType)] <- "Cycling Pericyte"
human_pos_marker_db_chunk8$CellType[human_pos_marker_db_chunk8$CellType == "Neural Retinal Progenitor Cell"] <- "Neural Retina Progenitor Cell"

human_pos_marker_db_chunk8$CellType[human_pos_marker_db_chunk8$CellType == "Non-ReCirculating Tissue-Resident Memory T Cell"] <- "Tissue-Resident Memory T Cell"
human_pos_marker_db_chunk8$CellType[human_pos_marker_db_chunk8$CellType == "Ovarian Stromal Cell"] <- "Ovarian Theca Cell"


## Update Tissue names
human_pos_marker_db_chunk8 <- human_pos_marker_db_chunk8 %>% clean_celltype_tissue()

