] <- "Embryonic Mesenchymal Stromal Cell"

# Define canonical fibroblast markers found broadly across lung fibroblasts
fibroblast_markers <- c(
  "COL1A1","COL1A2","COL3A1","DCN","LUM","FN1","PDGFRA","PDGFRB"
)

# Activated fibroblast markers commonly elevated in fibrosis and some activation states
activated_markers <- c(
  "ACTA2","TAGLN","POSTN","MMP1","MMP2","MMP9","FAP","CD248"
)

# Cancer-associated fibroblast (CAF)-specific or enriched markers
# These markers are examples from recent single-cell studies of CAF heterogeneity [1][5][7]
caf_markers <- c(
  "FAP", "POSTN", "ACTA2", "PDGFRA", "PDGFRB", "COL11A1", "COL10A1", "ADAMTS12", "AEBP1", "WNT7B"
)

# Fibrosis-associated fibroblast markers overlap with activated markers but focus on profibrotic genes
fibrosis_markers <- c(
  "ACTA2", "TAGLN", "POSTN", "MMP1", "MMP2", "MMP9", "COL1A1"
)

# Endothelial markers for non-fibroblast stromal cells
endo_markers <- c(
  "PECAM1", "VWF", "MADCAM1", "PLVAP"
)

# Pericyte / smooth muscle markers
pericyte_markers <- c(
  "MYH11","RGS5","PDGFRB","ACTA2"
)

# Mast cell marker
mast_markers <- c("KIT")

# Assign general lung fibroblasts in healthy or non-pathological samples
human_pos_marker_db_chunk9$CellType[
  human_pos_marker_db_chunk9$Tissue == "Lung" &
    !(human_pos_marker_db_chunk9$Condition %in% c("Pulmonary Fibrosis", "Sarcoidosis", "Lung Adenocarcinoma")) &
    human_pos_marker_db_chunk9$Marker %in% fibroblast_markers
] <- "Fibroblast"

# Assign fibrosis-associated fibroblasts in fibrotic lung conditions
human_pos_marker_db_chunk9$CellType[
  human_pos_marker_db_chunk9$Tissue == "Lung" &
    human_pos_marker_db_chunk9$Condition %in% c("Pulmonary Fibrosis", "Sarcoidosis") &
