] <- "Fibrosis-Associated Fibroblast"

# Assign cancer-associated fibroblasts (CAFs) in lung adenocarcinoma samples
human_pos_marker_db_chunk9$CellType[
  human_pos_marker_db_chunk9$Tissue == "Lung" &
    human_pos_marker_db_chunk9$Condition == "Lung Adenocarcinoma" &
