] <- "Mast Cell"

# Marker lists
pericyte_core_markers <- c("RGS5","CSPG4")  # CSPG4 if available
pericyte_support_markers <- c("PDGFRB","ACTA2","TAGLN","DES","CD146")

smooth_muscle_core_markers <- c("MYH11")  # Mature SMC-specific
smooth_muscle_support_markers <- c("ACTA2","TAGLN","DES","CD146")

# Step 1: Assign Smooth Muscle Cell if MYH11 detected (core SMC marker)
human_pos_marker_db_chunk9$CellType[
  human_pos_marker_db_chunk9$Tissue == "Lung" &
    human_pos_marker_db_chunk9$Marker == "MYH11"
] <- "Smooth Muscle Cell"

# Step 2: Assign Smooth Muscle Cell if supporting SMC markers co-expressed (excluding MYH11 rows)
# For example, if marker is ACTA2, TAGLN, DES, or CD146 but MYH11 not present,
# you might want to assign SMC only if other SMC markers also present per cell (requires aggregation)
# Here simplified: assign SMC if these markers present and cell not already assigned to Pericyte (requires data aggregation for robustness)

# Step 3: Assign Pericyte if pericyte core markers present, excluding already assigned SMC
human_pos_marker_db_chunk9$CellType[
  human_pos_marker_db_chunk9$Tissue == "Lung" &
    human_pos_marker_db_chunk9$Marker %in% pericyte_core_markers 
] <- "Pericyte"

# Step 4: Assign Pericyte if PDGFRB present but no MYH11 detected (mark PDGFRB only cells as Pericyte)
# To avoid overwriting smooth muscle assignments on MYH11+ rows, exclude those rows
human_pos_marker_db_chunk9$CellType[
  human_pos_marker_db_chunk9$Tissue == "Lung" &
    human_pos_marker_db_chunk9$Marker == "PDGFRB" &
    !(human_pos_marker_db_chunk9$Marker == "MYH11")
] <- "Pericyte"

human_pos_marker_db_chunk9$CellType[
