clean_celltype10 <- function(celltype) {
  # Handle NULL, NA, or non-character inputs
  if (is.null(celltype) || is.na(celltype) || !is.character(celltype)) {
    return("")
  }
  
  # Convert to UTF-8 encoding and remove invalid characters
  celltype <- iconv(celltype, to = "UTF-8", sub = "")
  
  # Convert to lowercase, trim whitespace, and standardize punctuation
  celltype <- tolower(trimws(celltype))
  celltype <- gsub("[[:punct:]]+", " ", celltype)  # Replace punctuation with space
  celltype <- gsub("\\s+", " ", celltype)         # Collapse multiple spaces
  
  return(celltype)
}
  
