filter_multi_upper <- function(x) {
  # Words to always ignore
  ignore_words <- c("GABAergic", "IgG", "IgM", "IgA")
  
  # Split words by space, slash, or dash
  x[sapply(strsplit(x, "[[:space:]/-]+"), function(words) {
    any(sapply(words, function(w) {
      # If word is in ignore list → skip
      if (w %in% ignore_words) return(FALSE)
      
      # If word matches CD marker pattern (CD + digits + dim|high|low) → skip
      if (grepl("^CD[0-9]+(dim|high|low)$", w)) return(FALSE)
      
      # Remove non-letters for uppercase/lowercase checks
      letters_only <- unlist(strsplit(gsub("[^A-Za-z]", "", w), ""))
      if (length(letters_only) == 0) return(FALSE)  # no letters at all
      
      uppers <- sum(grepl("[A-Z]", letters_only))
      lowers <- sum(grepl("[a-z]", letters_only))
      
      # Flag if more than one uppercase AND not all letters uppercase
      uppers > 1 && !(uppers == length(letters_only) && lowers == 0)
    }))
  })]
}

