# Assign conditions for specific disease-associated cell types
human_pos_marker_db_final$Condition[
  human_pos_marker_db_final$CellType == "Myeloid-Derived Suppressor Cell" &
    human_pos_marker_db_final$Tissue == "Immune System" &
    is.na(human_pos_marker_db_final$Condition)
] <- "Cancer"

human_pos_marker_db_final$Condition[
  human_pos_marker_db_final$CellType == "Neural Crest Stem Cell" &
    human_pos_marker_db_final$Tissue == "Melanoma" &
    is.na(human_pos_marker_db_final$Condition)
] <- "Melanoma"

human_pos_marker_db_final$Condition[
  human_pos_marker_db_final$CellType == "Myofibroblastic Cancer-associated Fibroblast" &
    human_pos_marker_db_final$Tissue == "Pancreas" &
