## Checking the marker availability ----

markerDictionary <- readRDS("R_Package_CelliVerse/data/markerDictionary.rds")
markerDictionary$human %>% view()

apply(markerDictionary$human, 2, function(i) sum(is.na(i)))

all(human_pos_marker_db_final$Marker %in% markerDictionary$human$Marker) # FALSE
final_missing_markers <- human_pos_marker_db_final$Marker[which(human_pos_marker_db_final$Marker %notin% markerDictionary$human$Marker)] %>% unique()
final_missing_markers %>% length()

## Invalid symbols in the human_pos_marker_db_final

library(HGNChelper)

# 1. HGNC check
hgnc_check <- HGNChelper::checkGeneSymbols(final_missing_markers, unmapped.as.na = TRUE)

hgnc_symbols <- hgnc_check$x[!is.na(hgnc_check$Suggested.Symbol)]

# 2. Non-standard IDs (clone IDs, LOC, RP11, AC, AL, CTD, etc.)
nonstandard_ids <- final_missing_markers[
  grepl("^LOC[0-9]+", final_missing_markers) |
    grepl("^(RP|CTD|AC|AL)[0-9]", final_missing_markers) |
    grepl("[0-9]+[A-Z]+[0-9]+\\.[0-9]+$", final_missing_markers)
]

nonstandard_ids_df <- gprofiler2::gconvert(query = nonstandard_ids, 
                                           organism = "hsapiens", mthreshold = 1, filter_na = F, 
                                           target = c("ENSG"))

human_pos_marker_db_final$Marker[human_pos_marker_db_final$Marker %in% nonstandard_ids_df$input[is.na(nonstandard_ids_df$target)]] <- NA
human_pos_marker_db_final <- human_pos_marker_db_final %>% dplyr::filter(!is.na(Marker))

nonstandard_ids_df_final <- nonstandard_ids_df %>% dplyr::filter(!is.na(target)) %>% dplyr::select(input)
colnames(nonstandard_ids_df_final) <- "Marker"

#___________________

# 3. Invalid/non-gene terms = leftovers
invalid_terms <- setdiff(final_missing_markers, c(hgnc_symbols, nonstandard_ids))

