#### Updating the dictionary ----

markerDictionary_human_complementary <- rbind(mapped_loci, nonstandard_ids_df_final, remaining_names_df_forMarging)
colnames(markerDictionary_human_complementary) <- c("Marker", "Symbol")
markerDictionary_human_complementary$Alias <- ""

markerDictionary_human_complementary_ENSG <- gprofiler2::gconvert(query = markerDictionary_human_complementary$Symbol, 
                                                    organism = "hsapiens", mthreshold = 1, filter_na = F, 
                                                    target = c("ENSG"))
markerDictionary_human_complementary$Ensembl <- markerDictionary_human_complementary_ENSG$target

markerDictionary_human_complementary_ENTREZGENE_ACC <- gprofiler2::gconvert(query = markerDictionary_human_complementary$Ensembl, 
                                                              organism = "hsapiens", mthreshold = 1, filter_na = F, 
