human_neg__missing_marker_df$UniProt <- human_neg__missing_marker_df_UNIPROT_GN$target

human_neg__missing_marker_df$Ensembl[which(human_neg__missing_marker_df$Symbol %in% GENCODEv44_Gene_id2name$V2)] <- 
  GENCODEv44_Gene_id2name$V1[match(human_neg__missing_marker_df$Symbol[which(human_neg__missing_marker_df$Symbol %in% GENCODEv44_Gene_id2name$V2)], GENCODEv44_Gene_id2name$V2)]

human_neg__missing_marker_df_ENTREZGENE_ACC <- mygene::getGenes(geneids = human_neg__missing_marker_df$Ensembl, fields = c("symbol", "entrezgene"), return.as = "DataFrame") %>% 
  as.data.frame()

human_neg__missing_marker_df$Entrez[is.na(human_neg__missing_marker_df$Entrez)] <- human_neg__missing_marker_df_ENTREZGENE_ACC$entrezgene[is.na(human_neg__missing_marker_df$Entrez)]


human_neg__missing_marker_df$Alias <- apply(human_neg__missing_marker_df[, c("Marker", "Symbol", "Entrez", "Ensembl", "UniProt")], 1, function(x) {
  # keep only non-empty values
  paste(x[x != ""], collapse = "|")
})

human_neg__missing_marker_df <- human_neg__missing_marker_df[,colnames(markerDictionary$human)]

#____________

# Updating the dictionary and saving it
all(human_neg_marker_db_final$Marker %in% markerDictionary$human$Marker) # FALSE
markerDictionary$human <- rbind(markerDictionary$human, human_neg__missing_marker_df)
all(human_neg_marker_db_final$Marker %in% markerDictionary$human$Marker) # TRUE

saveRDS(object = markerDictionary, file = "R_Package_CelliVerse/data/markerDictionary.rds")

#____________

human_neg_marker_db_final$Marker <- sapply(human_neg_marker_db_final$Marker, function(i) {
  tmp_symbols <- markerDictionary$human$Symbol[which(markerDictionary$human$Marker %in% i)] %>% unique()
  paste0(tmp_symbols, collapse = ",,,")
})

human_neg_marker_db_final <- human_neg_marker_db_final %>% tidyr::separate_rows(Marker, sep = ",,,")

#____________

##### Further refining the database ----

all(human_neg_marker_db_final$CellType %in% human_pos_marker_db_final$Original_CellType) # FALSE

human_neg_marker_db_final$CellType[which(human_neg_marker_db_final$CellType %notin% human_pos_marker_db_final$Original_CellType)] %>% unique()
human_neg_marker_db_final$CellType[human_neg_marker_db_final$CellType == "stem cell"] <- "Hematopoietic stem and progenitor cells"

all(human_neg_marker_db_final$CellType %in% human_pos_marker_db_final$Original_CellType) # TRUE

human_neg_marker_db_final$CellType <- human_pos_marker_db_final$CellType[match(human_neg_marker_db_final$CellType, human_pos_marker_db_final$Original_CellType)]

human_neg_marker_db_final$Parent <- ""
human_neg_marker_db_final <- human_neg_marker_db_final[,colnames(human_pos_marker_db_final)]

human_neg_marker_db_final <- human_neg_marker_db_final %>% dplyr::filter(!(CellType == "CD8+ Alpha-Beta T Cell" & Marker %in% "GZMB"))

human_neg_marker_db_final$CellType[human_neg_marker_db_final$CellType == "Pancreatic Acinar Cell"] <- "Acinar Cell"

#____________

human_neg_marker_db_final <- rbind(human_neg_marker_db_final,
                                   data.frame(
                                     ID = "UBERON:0000178",
                                     Tissue = "Blood",
                                     Condition = "Healthy",
                                     CellType = "Non-classical Monocyte",
                                     Marker = c("CCR2", "SELL", "FCGR1A", "S100A8", "S100A9", "LYZ", "VCAN", "CD163", 
                                                "MS4A7", "CD68", "IL1B", "CCR5", "CD14", "CD36", "ITGAM", "CD33"),
                                     Source = "Review",
                                     Parent = "",
                                     Original_CellType = "Non-classical Monocyte",
                                     Original_Tissue = "Blood",
                                     Original_Condition = "Healthy",
                                     Original_Marker = c("CCR2", "SELL", "FCGR1A", "S100A8", "S100A9", "LYZ", "VCAN", "CD163", 
                                                         "MS4A7", "CD68", "IL1B", "CCR5", "CD14", "CD36", "ITGAM", "CD33")
                                   ))

#____________

human_neg_marker_db_final <- human_neg_marker_db_final %>% dplyr::filter(!(CellType == "NK Cell" & 
                                                                             Marker %in% c("CCR5")
))

#____________

human_neg_marker_db_final <- human_neg_marker_db_final %>% dplyr::filter(!(CellType == "Non-classical Monocyte" & 
                                                                             Marker %in% c("CD68")
))

human_neg_marker_db_final$CellType[human_neg_marker_db_final$CellType %in% c("CD4+ Memory T Cell", 
                                                                             "CD4+ Positive Memory T Cell")] <- "Memory CD4+ T Cell"

human_neg_marker_db_final$CellType[human_neg_marker_db_final$CellType %in% c("CD8+ Memory T Cell")] <- "Memory CD8+ T Cell"

human_neg_marker_db_final$CellType[human_neg_marker_db_final$CellType %in% c("CD4+/CD8+",
                                                                             "CD8+ CD4+ T Cell")] <- "DP T Cell"

#____________________________

# Save Complete Negative Human Database ----

human_neg_marker_db_final <- structure(human_neg_marker_db_final,
                                       class = c("CelliVerse_Data", "data.frame"))

saveRDS(object = human_neg_marker_db_final, file = "CelliVerse-Project/Marker Database/human_neg_marker_db.rds")

