  dplyr::select(Uberon_ID, Uberon_tissue, Condition, CL_celltype, marker, resource)
colnames(accordion_v1_mouse_healthy_positive) <- c("ID", "Tissue", "Condition", "CellType", "Marker", "Source")

accordion_v1_mouse_disease_positive <- accordion_v1_mouse_disease %>% 
  dplyr::filter(marker_type == "positive") %>% 
  dplyr::select(DO_ID, Uberon_tissue, DO_diseasetype, NCIT_celltype, marker, resource)
