tissueCondition_types <- list(
  human = list(
    all_tissues = (rbind(human_pos_marker_db_final, human_neg_marker_db_final) %>% dplyr::select(Tissue) %>% unlist() %>% unname() %>% unique() %>% sort()),
    healthy_tissue = (rbind(human_pos_marker_db_final, human_neg_marker_db_final) %>% dplyr::filter(Condition == "Healthy") %>% dplyr::select(Tissue) %>% unlist() %>% unname() %>% unique() %>% sort()),
    diseased_tissue = (rbind(human_pos_marker_db_final, human_neg_marker_db_final) %>% dplyr::filter(Condition != "Healthy") %>% dplyr::select(Tissue) %>% unlist() %>% unname() %>% unique() %>% sort()),
    all_conditions = append("Healthy", (rbind(human_pos_marker_db_final, human_neg_marker_db_final) %>% dplyr::filter(Condition != "Healthy") %>% dplyr::select(Condition) %>% unlist() %>% unname() %>% unique() %>% sort())),
    diseased_tissueCondition = (rbind(human_pos_marker_db_final, human_neg_marker_db_final) %>% dplyr::filter(Condition != "Healthy") %>% dplyr::select(Tissue, Condition) %>% dplyr::distinct() %>% dplyr::arrange(Tissue))
    ),
  mouse = list(
    all_tissues = (rbind(accordion_v1_mouse_positive, accordion_v1_mouse_negative) %>% dplyr::select(Tissue) %>% unlist() %>% unname() %>% unique() %>% sort()),
    healthy_tissue = (rbind(accordion_v1_mouse_positive, accordion_v1_mouse_negative) %>% dplyr::filter(Condition == "Healthy") %>% dplyr::select(Tissue) %>% unlist() %>% unname() %>% unique() %>% sort()),
    diseased_tissue = (rbind(accordion_v1_mouse_positive, accordion_v1_mouse_negative) %>% dplyr::filter(Condition != "Healthy") %>% dplyr::select(Tissue) %>% unlist() %>% unname() %>% unique() %>% sort()),
    all_conditions = append("Healthy", (rbind(accordion_v1_mouse_positive, accordion_v1_mouse_negative) %>% dplyr::filter(Condition != "Healthy") %>% dplyr::select(Condition) %>% unlist() %>% unname() %>% unique() %>% sort())),
    diseased_tissueCondition = (rbind(accordion_v1_mouse_positive, accordion_v1_mouse_negative) %>% dplyr::filter(Condition != "Healthy") %>% dplyr::select(Tissue, Condition) %>% dplyr::distinct() %>% dplyr::arrange(Tissue))
    )
  )

tissueCondition_types <- structure(tissueCondition_types,
                                   class = c("CelliVerse_Data", "list"))

#________________________

# Save the tissueCondition_types
saveRDS(object = tissueCondition_types, file = "R_Package_CelliVerse/data/tissueCondition_types.rds")

