## Preparing the mouse dictionary ----

markerDictionary$mouse <- data.frame(Marker = rbind(accordion_v1_mouse_positive, accordion_v1_mouse_negative) %>% dplyr::select(Marker) %>% dplyr::distinct() %>% unlist() %>% unname() %>% unique() %>% sort())
markerDictionary$mouse <- markerDictionary$mouse %>% dplyr::mutate(
  Symbol = Marker, Alias = Marker)

mouse_marker_df_ENSG <- gprofiler2::gconvert(query = markerDictionary$mouse$Symbol, 
                                                          organism = "mmusculus", mthreshold = 1, filter_na = F, 
                                                          target = c("ENSG"))
markerDictionary$mouse$Ensembl <- mouse_marker_df_ENSG$target

mouse_marker_df_ENTREZGENE_ACC <- gprofiler2::gconvert(query = markerDictionary$mouse$Ensembl, 
                                                                    organism = "mmusculus", mthreshold = 1, filter_na = F, 
                                                                    target = c("ENTREZGENE_ACC"))
markerDictionary$mouse$Entrez <- mouse_marker_df_ENTREZGENE_ACC$target

mouse_marker_df_UNIPROT_GN <- gprofiler2::gconvert(query = markerDictionary$mouse$Symbol, 
                                                                organism = "mmusculus", mthreshold = 1, filter_na = F, 
                                                                target = c("UNIPROT_GN"))
markerDictionary$mouse$UniProt <- mouse_marker_df_UNIPROT_GN$target

markerDictionary$mouse <- markerDictionary$mouse[, colnames(markerDictionary$human)]

markerDictionary$mouse[is.na(markerDictionary$mouse)] <- ""

markerDictionary$mouse$Alias <- apply(markerDictionary$mouse %>% dplyr::select(Alias, Entrez, Ensembl, UniProt), 1, function(x) {
  # keep only non-empty values
  paste(x[x != ""], collapse = "|")
})
  
#____________

markerDictionary$human <- markerDictionary$human %>% dplyr::arrange(Symbol)

#____________


markerDictionary <- structure(markerDictionary,
                         class = c("CelliVerse_Data", "list"))

#________________________

# Save the markerDictionary
saveRDS(object = markerDictionary, file = "R_Package_CelliVerse/data/markerDictionary.rds")

